public static class HighwayAssets {
 const string Root="Assets/HarborValeGreybox/Highway";static string generated;static int meshId;static HighwayNetwork network;static Material asphalt,concrete,white,yellow,green,metal;static Transform parent;
 static Material Mat(string name,Color color){string path=Root+"/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Glossiness",.1f);return m;}
 static GameObject Box(string name,Transform p,Vector3 center,Vector3 size,Material material,bool collision=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(p,false);g.transform.localPosition=center;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=material;if(!collision)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;return g;}
 sealed class Shape {public List<Vector3> vertices=new List<Vector3>();public List<int> triangles=new List<int>();public void Face(Vector3 a,Vector3 b,Vector3 c,Vector3 d,Vector3 normal){int i=vertices.Count;vertices.AddRange(new[]{a,b,c,d});if(Vector3.Dot(Vector3.Cross(b-a,c-a),normal)>=0)triangles.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});else triangles.AddRange(new[]{i,i+2,i+1,i,i+3,i+2});}}
 static void MeshObject(string name,Shape shape,Material material,bool collision){if(shape.vertices.Count==0)return;var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(shape.vertices);mesh.SetTriangles(shape.triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,generated+"/"+(meshId++)+".asset");var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;if(collision)g.AddComponent<MeshCollider>().sharedMesh=mesh;g.isStatic=true;}
 static void Surface(string name,RoutePoint[] points,bool closed,float width,Material mat,float lift=0,bool collision=true){var shape=new Shape();int count=closed?points.Length:points.Length-1;for(int i=0;i<count;i++){int j=(i+1)%points.Length;var a=HighwayNetwork.Offset(points,i,-width/2,closed)+Vector3.up*lift;var b=HighwayNetwork.Offset(points,i,width/2,closed)+Vector3.up*lift;var c=HighwayNetwork.Offset(points,j,width/2,closed)+Vector3.up*lift;var d=HighwayNetwork.Offset(points,j,-width/2,closed)+Vector3.up*lift;shape.Face(a,b,c,d,Vector3.up);}MeshObject(name,shape,mat,collision);}
 static void Prism(string name,RoutePoint[] points,bool closed,float offset,float width,float below,float height,Func<int,bool> include=null){var shape=new Shape();int count=closed?points.Length:points.Length-1;for(int i=0;i<count;i++){if(include!=null&&!include(i))continue;int j=(i+1)%points.Length;var right=HighwayNetwork.Right(points,i,closed);var al=HighwayNetwork.Offset(points,i,offset-width/2,closed)+Vector3.up*below;var ar=HighwayNetwork.Offset(points,i,offset+width/2,closed)+Vector3.up*below;var bl=HighwayNetwork.Offset(points,j,offset-width/2,closed)+Vector3.up*below;var br=HighwayNetwork.Offset(points,j,offset+width/2,closed)+Vector3.up*below;var up=Vector3.up*height;shape.Face(al+up,ar+up,br+up,bl+up,Vector3.up);shape.Face(al,bl,br,ar,Vector3.down);shape.Face(al,al+up,bl+up,bl,-right);shape.Face(ar,br,br+up,ar+up,right);bool first=i==0&&!closed||include!=null&&!include((i-1+count)%count),last=i==count-1&&!closed||include!=null&&!include((i+1)%count);if(first)shape.Face(al,ar,ar+up,al+up,-(bl-al).normalized);if(last)shape.Face(bl,bl+up,br+up,br,(bl-al).normalized);}MeshObject(name,shape,concrete,height>0);}
 static float NearPath(Vector3 p,RoutePoint[] points,out float y){float best=float.MaxValue;y=0;for(int i=1;i<points.Length;i++){var a=points[i-1].Position;var b=points[i].Position;var ab=b-a;ab.y=0;var v=p-a;v.y=0;float t=Mathf.Clamp01(Vector3.Dot(v,ab)/ab.sqrMagnitude);var q=Vector3.Lerp(a,b,t);float dd=(new Vector2(q.x-p.x,q.z-p.z)).sqrMagnitude;if(dd<best){best=dd;y=q.y;}}return Mathf.Sqrt(best);}
 static bool MainRailOpen(int i,float offset){var point=HighwayNetwork.Offset(network.center,i,offset,true);foreach(var ramp in network.ramps){if(ramp.merge=="none")continue;float y;if(NearPath(point,ramp.points,out y)<ramp.width/2+2&&Mathf.Abs(y-point.y)<.45f)return true;}return false;}
 static bool RampRailAllowed(HighwayRamp ramp,int i){if(i<3||i>=ramp.points.Length-4)return false;var p=ramp.points[i].Position;foreach(var other in network.ramps){if(ReferenceEquals(other,ramp))continue;float otherY;if(NearPath(p,other.points,out otherY)<(ramp.width+other.width)/2+2&&Mathf.Abs(otherY-p.y)<.6f)return false;}if(p.y-HighwayNetwork.GroundHeight(p.z)<2)return false;float y;return NearPath(p,network.center,out y)>16||Mathf.Abs(y-p.y)>.5f;}
 static void Paint(RoutePoint[] points,bool closed,float offset,float width,Shape shape,bool dashed){float distance=0;int count=closed?points.Length:points.Length-1;for(int i=0;i<count;i++){int j=(i+1)%points.Length;float step=Vector3.Distance(points[i].Position,points[j].Position);if(!dashed||distance%12<5){var a=HighwayNetwork.Offset(points,i,offset-width/2,closed)+Vector3.up*.018f;var b=HighwayNetwork.Offset(points,i,offset+width/2,closed)+Vector3.up*.018f;var c=HighwayNetwork.Offset(points,j,offset+width/2,closed)+Vector3.up*.018f;var d=HighwayNetwork.Offset(points,j,offset-width/2,closed)+Vector3.up*.018f;shape.Face(a,b,c,d,Vector3.up);}distance+=step;}}
 static void Piers(RoutePoint[] points,bool closed,float width,string label){for(int i=0;i<points.Length;i+=14){var p=points[i].Position;float ground=HighwayNetwork.GroundHeight(p.z),height=p.y-ground-.5f;if(height<2)continue;bool crossing=false;if(!ReferenceEquals(points,network.center)){float mainY;if(NearPath(p,network.center,out mainY)<network.roadWidth/2+4&&mainY>ground+2&&mainY<p.y-3)crossing=true;}foreach(var road in network.ramps){if(ReferenceEquals(road.points,points))continue;float y;if(NearPath(p,road.points,out y)<road.width/2+3&&y>ground+2&&y<p.y-3){crossing=true;break;}}if(crossing)continue;var right=HighwayNetwork.Right(points,i,closed);foreach(float side in width>20?new[]{-7f,7f}:new[]{0f})Box(label+" pier",parent,new Vector3(p.x,ground+height/2,p.z)+right*side,new Vector3(1.8f,height,1.8f),concrete);if(width>20){var tangent=points[(i+1)%points.Length].Position-p;tangent.y=0;Box(label+" crossbeam",parent,p-Vector3.up*.9f,new Vector3(width-1,1.1f,2.5f),concrete).transform.rotation=Quaternion.LookRotation(tangent);}}}
 static void Text(string name,Transform p,string value,Vector3 pos,float size,int fontSize=64){var g=new GameObject(name);g.transform.SetParent(p,false);g.transform.localPosition=pos;var t=g.AddComponent<TextMesh>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=fontSize;t.characterSize=size;t.text=value;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=Color.black;g.GetComponent<Renderer>().sharedMaterial=t.font.material;}
 static void LimitSign(Vector3 point,Vector3 forward,float mph){var root=new GameObject("Posted "+mph+" mph / "+DrivingUnits.FromMph(mph).ToString("F0")+" kmh");root.transform.SetParent(parent,false);root.transform.SetPositionAndRotation(point,Quaternion.LookRotation(forward));Box("Sign pole",root.transform,new Vector3(0,1.35f,0),new Vector3(.1f,2.7f,.1f),metal);Box("Speed panel",root.transform,new Vector3(0,2.6f,-.04f),new Vector3(1.45f,1.9f,.12f),white,false);Text("Speed",root.transform,mph.ToString("F0"),new Vector3(0,2.98f,-.115f),.29f);Text("Unit",root.transform,"MPH",new Vector3(0,2.43f,-.115f),.15f);Text("Equivalent",root.transform,DrivingUnits.FromMph(mph).ToString("F0")+" km/h",new Vector3(0,1.99f,-.115f),.10f);}
 public static void Build(){Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Resources");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff");generated=Root+"/Generated/"+stamp;Directory.CreateDirectory(generated);meshId=0;AssetDatabase.Refresh();network=HighwayNetwork.Load();asphalt=Mat("Highway asphalt",new Color(.16f,.18f,.20f));concrete=Mat("Highway concrete",new Color(.48f,.49f,.47f));white=Mat("Highway white",new Color(.90f,.90f,.84f));yellow=Mat("Highway yellow",new Color(.90f,.70f,.16f));green=Mat("Highway guide green",new Color(.05f,.33f,.26f));metal=Mat("Highway sign metal",new Color(.35f,.38f,.39f));var root=new GameObject("HW01 | HARBOR RING EXPRESSWAY | 3 + median + 3");parent=root.transform;try{Surface("Six-lane mainline / physical asphalt",network.center,true,network.roadWidth,asphalt);Prism("Mainline bridge deck",network.center,true,0,network.roadWidth,-.45f,.425f);Prism("2.4m central concrete median",network.center,true,0,2.4f,0,.9f);foreach(float side in new[]{-1f,1f})Prism("Outer safety barrier "+side,network.center,true,side*13.75f,.35f,0,.8f,i=>!MainRailOpen(i,side*13.75f));var paint=new Shape();foreach(float offset in new[]{-12f,-8.4f,-4.8f,4.8f,8.4f,12f})Paint(network.center,true,offset,.13f,paint,Mathf.Abs(offset)<11);MeshObject("Highway white edges and dashed lane lines",paint,white,false);var middle=new Shape();Paint(network.center,true,-1.35f,.12f,middle,false);Paint(network.center,true,1.35f,.12f,middle,false);MeshObject("Median yellow edges",middle,yellow,false);Piers(network.center,true,network.roadWidth,"Mainline");foreach(var ramp in network.ramps){Surface(ramp.id+" / "+ramp.name,ramp.points,false,ramp.width,asphalt);Prism(ramp.id+" deck",ramp.points,false,0,ramp.width,-.35f,.325f);foreach(float side in new[]{-1f,1f})Prism(ramp.id+" rail "+side,ramp.points,false,side*(ramp.width/2-.12f),.24f,0,.75f,i=>RampRailAllowed(ramp,i));var edge=new Shape();Paint(ramp.points,false,-ramp.width/2+.18f,.10f,edge,false);Paint(ramp.points,false,ramp.width/2-.18f,.10f,edge,false);MeshObject(ramp.id+" edge paint",edge,white,false);if(ramp.lanes==2){var centerPaint=new Shape();Paint(ramp.points,false,0,.12f,centerPaint,false);MeshObject(ramp.id+" two-way center stripe",centerPaint,yellow,false);}Piers(ramp.points,false,ramp.width,ramp.id);int sign=Math.Min(15,ramp.points.Length-2);LimitSign(ramp.points[sign].Position+HighwayNetwork.Right(ramp.points,sign,false)*(ramp.width/2+1.2f),ramp.points[sign+1].Position-ramp.points[sign].Position,ramp.speedLimitMph);}
 for(int i=30;i<network.center.Length;i+=100){var tangent=network.center[(i+1)%network.center.Length].Position-network.center[i].Position;LimitSign(HighwayNetwork.Offset(network.center,i,15.2f,true),tangent,70);LimitSign(HighwayNetwork.Offset(network.center,i,-15.2f,true),-tangent,70);}var gateway=new GameObject("North highway access / guide");gateway.transform.SetParent(parent,false);gateway.transform.position=network.ramps[0].points[0].Position+new Vector3(7,0,5);gateway.transform.rotation=Quaternion.identity;Box("Guide panel",gateway.transform,new Vector3(0,3.4f,0),new Vector3(5,2.2f,.15f),green,false);Text("Highway access",gateway.transform,"EXPRESSWAY\nNORTH GATE",new Vector3(0,3.4f,-.10f),.18f);var guide=gateway.transform.GetChild(gateway.transform.childCount-1).GetComponent<TextMesh>();guide.color=Color.white;Box("Guide support",gateway.transform,new Vector3(-2,1.7f,0),new Vector3(.12f,3.4f,.12f),metal);Box("Guide support",gateway.transform,new Vector3(2,1.7f,0),new Vector3(.12f,3.4f,.12f),metal);
 string prefab=Root+"/Resources/HarborExpressway.prefab";if(File.Exists(prefab)){Directory.CreateDirectory("Verification/Highway/Backups");File.Copy(prefab,"Verification/Highway/Backups/HarborExpressway-"+stamp+".prefab");}PrefabUtility.SaveAsPrefabAsset(root,prefab);AssetDatabase.SaveAssets();Directory.CreateDirectory("Verification/Highway");File.WriteAllText("Verification/Highway/authoring.txt","Generated mesh folder="+generated+"\nMeshes="+meshId+"\nSource city scene untouched\n");}finally{UnityEngine.Object.DestroyImmediate(root);}}
}
